@Component("customer-entity-projector")
public class CustomerEntityProjector implements EntityProjector<Customer>{
		
	// core constructor
	public CustomerEntityProjector(ProjectorRegistry registry,
										CustomerRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Customer> getEntityClass() {
		return Customer.class;
	}

    /*
	 * Insert a Customer
	 * 
     * @param	entity Customer
     */
    public Customer create( Customer entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Customer
	 * 
     * @param	entity Customer
     */
    public Customer update( Customer entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Customer
	 * 
     * @param	id		UUID
     */
    public Customer delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Customer entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    


    /*
     * Add to the Enterprises
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Customer
     */
    public Customer addToEnterprises( UUID parentId, Enterprise addTo ) {
	    LOGGER.info("handling AssignEnterprisesToCustomerEvent - " );
	    
	    Customer parentEntity = repository.findById(parentId).get();
	    Enterprise child = registry.project( Enterprise.class, addTo.getEnterpriseId());
	    
	    parentEntity.getEnterprises().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Enterprises
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Customer
     */
	public Customer removeFromEnterprises( UUID parentId, Enterprise removeFrom ) {
	    LOGGER.info("handling RemoveEnterprisesFromCustomerEvent " );
	
	    Customer parentEntity = repository.findById(parentId).get();
	    Enterprise child = registry.project( Enterprise.class, removeFrom.getEnterpriseId());
	    
	    parentEntity.getEnterprises().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the SalesOrders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Customer
     */
    public Customer addToSalesOrders( UUID parentId, SalesOrder addTo ) {
	    LOGGER.info("handling AssignSalesOrdersToCustomerEvent - " );
	    
	    Customer parentEntity = repository.findById(parentId).get();
	    SalesOrder child = registry.project( SalesOrder.class, addTo.getSalesOrderId());
	    
	    parentEntity.getSalesOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the SalesOrders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Customer
     */
	public Customer removeFromSalesOrders( UUID parentId, SalesOrder removeFrom ) {
	    LOGGER.info("handling RemoveSalesOrdersFromCustomerEvent " );
	
	    Customer parentEntity = repository.findById(parentId).get();
	    SalesOrder child = registry.project( SalesOrder.class, removeFrom.getSalesOrderId());
	    
	    parentEntity.getSalesOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Customer via an FindCustomerQuery
     * @return 	query	FindCustomerQuery
     */
    @SuppressWarnings("unused")
    public Customer find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Customer - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Customers
     *
     * @param	query	FindAllCustomerQuery 
     * @return 	List<Customer> 
     */
    @SuppressWarnings("unused")
    public List<Customer> findAll( FindAllCustomerQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Customer - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final CustomerRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(CustomerEntityProjector.class.getName());

}
